#!/bin/sh

set -e # Exit immediately if a command exits with a non-zero status.
set -u # Treat unset variables as an error.

#
# Add window switching keys to the Openbox configuration.
#
# The desktop has no taskbar and no window menu, and the web GUI cannot deliver
# the Alt+Tab that Openbox binds by default: the operating system of whoever is
# watching the GUI consumes it before the browser sees it. These bindings give
# the web GUI a way to cycle through the application's windows anyway.
#
# Openbox reads the configuration generated by the base image's 10-openbox.sh,
# which has no <keyboard> section and therefore falls back to Openbox's built-in
# defaults (Alt+Tab and Alt+Shift+Tab). Adding a <keyboard> section replaces
# those defaults, so they are repeated below.
#

RC_FILE=/var/run/openbox/rc.xml

if [ ! -f "${RC_FILE}" ]; then
    echo "ERROR: ${RC_FILE} not found; did the base image's 10-openbox.sh run?" >&2
    exit 1
fi

if grep -q '<keyboard>' "${RC_FILE}"; then
    echo "ERROR: ${RC_FILE} already has a <keyboard> section." >&2
    exit 1
fi

if ! grep -q '^</openbox_config>$' "${RC_FILE}"; then
    echo "ERROR: ${RC_FILE} does not end with </openbox_config> as expected." >&2
    exit 1
fi

TMP_FILE="$(mktemp)"

# Everything up to the closing tag, then the bindings, then the closing tag.
sed '/^<\/openbox_config>$/,$d' < "${RC_FILE}" > "${TMP_FILE}"
cat >> "${TMP_FILE}" <<'EOF'
  <keyboard>
    <!-- Cycle through the windows of the current desktop. -->
    <keybind key="A-Tab"><action name="NextWindow"><dialog>no</dialog><bar>no</bar><raise>yes</raise></action></keybind>
    <keybind key="A-S-Tab"><action name="PreviousWindow"><dialog>no</dialog><bar>no</bar><raise>yes</raise></action></keybind>
    <keybind key="C-F6"><action name="NextWindow"><dialog>no</dialog><bar>no</bar><raise>yes</raise></action></keybind>
    <keybind key="C-S-F6"><action name="PreviousWindow"><dialog>no</dialog><bar>no</bar><raise>yes</raise></action></keybind>
  </keyboard>
</openbox_config>
EOF

# Overwrite in place to keep the ownership and permissions of the original.
cat "${TMP_FILE}" > "${RC_FILE}"
rm -f "${TMP_FILE}"

